mapper.select:
select su.login_name , ac.userId, ac.userName, ac.partenId, ac.partenName, ac.deptId, ac.deptName, ac.hxkt, ac.zxktxj, ac.zxktxjys, ac.cgzh, ac.xslw, ac.jczz, ac.zl, ac.rz, ac.jl, ac.jzbg, alt.zcgjjjkyxm, alt.zcsbjjjkyxm, alt.zcsbjjgxm, alt.zcsbjzxkyxm, alt.zctjjxhjkyxm, alt.zcxjjxglxmywyys, alt.zcxjjxglxmywyyx from Alltotle_score ac left join sys_user su on su.user_id = ac.userId left join Alltotle alt on alt.userId = ac.userId
AND ac.partenId IN
#{dictVal}
AND ac.partenName LIKE CONCAT('%', #{pname}, '%')
AND ac.deptName LIKE CONCAT('%', #{dname}, '%')
AND ac.userName LIKE CONCAT('%', #{userName}, '%')
AND ac.userId = #{scopeUserId}
AND ac.deptId = #{scopeDeptId}
AND ac.partenId = #{collegeParentId}
order by ac.partenName asc, ac.deptName asc, su.login_name asc
